import{_ as e,o as a,c as i,a2 as n}from"./chunks/framework.7w-lhQN6.js";const r=JSON.parse('{"title":"Codex","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/codex.md","filePath":"ko/guide/codex.md","lastUpdated":1793550481000}'),d={name:"ko/guide/codex.md"};function t(o,s,l,p,h,c){return a(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="codex" tabindex="-1">Codex <a class="header-anchor" href="#codex" aria-label="Permalink to &quot;Codex&quot;">​</a></h1><p>이 문서를 끝내면 Codex에 MCP Lens 플러그인이 설치되고 훅이 신뢰된 상태가 되어, Codex 세션의 모든 MCP 툴 호출이 로컬에 기록되고 Codex로 쓰는 서버들에 대해 <code>mcp-lens report</code>의 <code>calls</code> 열이 더 이상 0에 머물지 않는다.</p><h2 id="쉬운-방법-확장이-대신-하게-한다" tabindex="-1">쉬운 방법: 확장이 대신 하게 한다 <a class="header-anchor" href="#쉬운-방법-확장이-대신-하게-한다" aria-label="Permalink to &quot;쉬운 방법: 확장이 대신 하게 한다&quot;">​</a></h2><p>VS Code 확장을 쓰고 있다면 <code>MCP Lens: Install Hooks for All Clients</code> 커맨드를 실행한다. 그러면 이 플러그인이 자동으로 설치된다. <a href="/MCPLens/ko/guide/vscode-extension">VS Code 확장</a> 참고. 이 경로를 탔다면 아래 수동 설치 절은 건너뛰고 <a href="#설치-후">설치 후</a>로 바로 간다. 이 절은 건너뛰지 않는다. 플러그인이 어떻게 설치됐든 Codex는 훅의 해시를 그 절에서 신뢰하기 전까지 훅을 실행하지 않는다.</p><h2 id="플러그인을-수동으로-설치한다" tabindex="-1">플러그인을 수동으로 설치한다 <a class="header-anchor" href="#플러그인을-수동으로-설치한다" aria-label="Permalink to &quot;플러그인을 수동으로 설치한다&quot;">​</a></h2><p>Codex 플러그인은 로컬 마켓플레이스 스냅샷에서 등록하며, 이 스냅샷은 저장소 빌드가 만든다. 먼저 저장소를 빌드하고, 그 스냅샷을 <code>codex</code> CLI에 등록한다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/seodduu/MCPLens.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MCPLens</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                          # also builds packages/extension/dist/codex-marketplace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketplace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/extension/dist/codex-marketplace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp-lens@mcplens</span></span></code></pre></div><p><code>codex plugin list --json</code>을 실행하면 이제 <code>installed</code> 아래 <code>mcp-lens@mcplens</code>가 보인다.</p><h2 id="수집하는-것" tabindex="-1">수집하는 것 <a class="header-anchor" href="#수집하는-것" aria-label="Permalink to &quot;수집하는 것&quot;">​</a></h2><p>플러그인은 <code>SessionStart</code>, <code>PreToolUse</code>, <code>PostToolUse</code>, <code>Stop</code> 훅을 등록하며 번들된 훅 러너만 쓴다. 런타임을 내려받지 않고 MCP Lens 데이터베이스나 네트워크도 열지 않으며, MCP 호출의 최소 메타데이터만 기록해 <code>~/.mcplens/inbox</code>에 원자적으로 큐잉한다. 툴 입력, 툴 응답, 프롬프트 텍스트, 어시스턴트 메시지 본문은 보관하지 않고 Codex의 원본 세션 로그도 그대로 둔다.</p><h2 id="설치-후" tabindex="-1">설치 후 <a class="header-anchor" href="#설치-후" aria-label="Permalink to &quot;설치 후&quot;">​</a></h2><p>Codex는 플러그인에 번들된 훅을, 현재 훅 정의의 해시를 검토하고 신뢰하기 전까지 건너뛴다. Codex 안에서 <code>/hooks</code>를 열어 MCP Lens 훅 정의를 검토하고 현재 해시를 신뢰한다. 해시가 바뀔 때마다 이 과정을 다시 한다. 훅 상태가 바뀐 뒤에는 새 Codex 세션을 시작한다.</p><p>수집을 멈추려면 플러그인 등록을 비활성화하거나 제거한다. 제거하면 플러그인이 삭제된다.</p>`,13)])])}const F=e(d,[["render",t]]);export{r as __pageData,F as default};
